import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0002: Why External-process Plugins in v1","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0002-why-external-process-plugins.md","filePath":"adr/ADR-0002-why-external-process-plugins.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0002-why-external-process-plugins.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0002-why-external-process-plugins-in-v1" tabindex="-1">ADR-0002: Why External-process Plugins in v1 <a class="header-anchor" href="#adr-0002-why-external-process-plugins-in-v1" aria-label="Permalink to “ADR-0002: Why External-process Plugins in v1”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: docs/guide/plugins.md §4, ADR-0003</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>Plugins carry arbitrary probe and recovery logic (mihomo, cloudflared, OpenClash, custom scripts); author languages are unpredictable and plugin code quality is uncontrolled: they will crash, hang, or write malformed output.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Plugins are independent child processes talking to the core via stdio (custos-plugin-host): <code>PluginSupervisor</code> handles spawn/handshake/capability validation/crash restart (rolling window + give-up marker); the core process never exits because a plugin died; after a crash the plugin&#39;s resources are marked unprobeable per §4.5 and a notification is raised.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>In-process dynamic library (dlopen/cdylib)</strong>: one crash kills the core — isolation is zero; fragile ABI; directly conflicts with the P1 gate &quot;plugin crash must not exit core.&quot;</li><li><strong>Built-in only (no plugins)</strong>: extensions require a core release; the community cannot contribute scenario-specific capabilities.</li><li><strong>WASM</strong>: good sandbox but host interfaces (file/process/network) all need a custom ABI — too costly for v1.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: physical fault isolation; any language that writes to stdout works; crash-restart policy evolves independently; clean permission boundary (plugins hold no core memory or credentials). Cons: IPC serialization overhead (JSON line protocol); process lifecycle management is complex (zombies, stderr backpressure); handshake/version/capability validation requires protocol discipline.</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li>ADR-0003 (JSON-RPC over stdio) implements the protocol layer.</li><li>Continuous stderr reader thread prevents pipe-full blocking (tests: chatty_stderr_is_drained_and_capped).</li><li>The Python inbound script loader (todo P1) reuses the same contract: timeout/permission/budget identical.</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};